#!/usr/bin/env node --import tsx
/**
 * Inspect the actual code being generated by Phase 3
 */

import { v } from '../src/index.ts';

// Create a simple schema
const UserSchema = v.object({
  name: v.string(),
  age: v.number(),
  email: v.string(),
});

// Get the compiled validator
const validator = v.array(UserSchema);

// The validator has a compiled function - let's inspect it
console.log('🔍 Inspecting Phase 3 Generated Code\n');
console.log('Schema: { name: string, age: number, email: string }\n');

// Try to inspect the generated function
// Note: The actual generated code is in the closure, but we can test its behavior

const testData = [
  { name: 'Alice', age: 30, email: 'alice@example.com' },
  { name: 'Bob', age: 25, email: 'bob@example.com' },
];

console.log('Testing validator on sample data...');
const result = validator.validate(testData);
console.log('Result:', result);
console.log('\n');

// Now let's manually create the same validator to see the generated code
console.log('='.repeat(60));
console.log('MANUAL INSPECTION: What Phase 3 generates');
console.log('='.repeat(60));
console.log('\n');

// This is what our code generation does:
const checks: string[] = [];
const validatorClosures: Record<string, (value: unknown) => boolean> = {};

// For each property:
// name: v.string() -> inline check
checks.push(`if (typeof obj.name !== 'string') return false;`);

// age: v.number() -> inline check
checks.push(`if (typeof obj.age !== 'number' || Number.isNaN(obj.age)) return false;`);

// email: v.string() -> inline check
checks.push(`if (typeof obj.email !== 'string') return false;`);

const fnBody = `
  if (typeof data !== 'object' || data === null) return false;
  const obj = data;
  ${checks.join('\n  ')}
  return true;
`;

console.log('Generated function body:');
console.log(fnBody);
console.log('\n');

// Create the function
const generatedFn = new Function('validatorClosures', `
  return function(data) {
    ${fnBody}
  }
`)(validatorClosures) as (data: unknown) => boolean;

console.log('Testing manually generated function...');
console.log('Valid object:', generatedFn({ name: 'Alice', age: 30, email: 'alice@example.com' }));
console.log('Invalid object (missing name):', generatedFn({ age: 30, email: 'alice@example.com' }));
console.log('Invalid object (wrong type):', generatedFn({ name: 123, age: 30, email: 'alice@example.com' }));
console.log('\n');

console.log('='.repeat(60));
console.log('COMPARISON: What valibot likely does');
console.log('='.repeat(60));
console.log('\n');

console.log('Valibot probably generates similar code, but with additional overhead:');
console.log('- Error message collection (we return boolean only)');
console.log('- Schema metadata tracking');
console.log('- Type transformation support');
console.log('- More complex validation pipeline');
console.log('\n');

console.log('Our advantage:');
console.log('- ✅ Pure boolean validation (no error objects)');
console.log('- ✅ Minimal overhead');
console.log('- ✅ Direct property access (obj.name vs obj[key])');
console.log('- ✅ Inline type checks (no function calls)');
